  1182  static void checkExtensions(struct ndpi_detection_module_struct *ndpi_struct,
  1183                              struct ndpi_flow_struct * const flow, int is_dtls,
  1184                              u_int16_t extension_id, u_int16_t extension_len, u_int16_t extension_payload_offset)
  1185  {
  1186    struct ndpi_packet_struct const * const packet = &ndpi_struct->packet;
  1187
  1188    if(extension_payload_offset + extension_len > packet->payload_packet_len)
  1189    {
  1190  #ifdef DEBUG_TLS
  1191      printf("[TLS] extension length exceeds remaining packet length: %u > %u.\n",
  1192             extension_len, packet->payload_packet_len - extension_payload_offset);
  1193  #endif
  1194      ndpi_set_risk(ndpi_struct, flow, NDPI_TLS_SUSPICIOUS_EXTENSION);
  1195      return;
  1196    }
  1197
  1198    /* see: https://www.wireshark.org/docs/wsar_html/packet-tls-utils_8h_source.html */
  1199    static u_int16_t const allowed_non_iana_extensions[] = {
  1200      65486 /* ESNI */, 13172 /* NPN - Next Proto Neg */, 17513 /* ALPS */,
  1201      30032 /* Channel ID */, 65445 /* QUIC transport params */,
  1202      /* GREASE extensions */
  1203      2570, 6682, 10794, 14906, 19018, 23130, 27242,
  1204      31354, 35466, 39578, 43690, 47802, 51914, 56026,
  1205      60138, 64250,
  1206      /* Groups */
  1207      1035, 10794, 16696, 23130, 31354, 35466, 51914,
  1208      /* Ciphers */
  1209      102, 129, 52243, 52244, 57363, 65279, 65413
  1210    };
  1211    size_t const allowed_non_iana_extensions_size = sizeof(allowed_non_iana_extensions) /
  1212                                                    sizeof(allowed_non_iana_extensions[0]);
  1213
  1214    /* see: https://www.iana.org/assignments/tls-extensiontype-values/tls-extensiontype-values.xhtml */
  1215    if(extension_id > 59 && extension_id != 65281)
  1216    {
  1217      u_int8_t extension_found = 0;
  1218      for (size_t i = 0; i < allowed_non_iana_extensions_size; ++i)
  1219      {
  1220        if(allowed_non_iana_extensions[i] == extension_id)
  1221        {
  1222          extension_found = 1;
  1223          break;
  1224        }
  1225      }
  1226      if(extension_found == 0)
  1227      {
  1228  #ifdef DEBUG_TLS
